    표5_매튜헨리: [
        {"영어원문":"This same Word, that was God, was in the beginning with God; from eternity the same in substance, equal in power and glory.", "한국어번역":"하나님이신 이 말씀은 태초에 하나님과 함께 계셨으니 영원 전부터 본질이 같으시고 능력과 영광이 동등하셨다.", "핵심통찰":"아들의 영원한 동등성은 태초부터의 사실"},
        {"영어원문":"The repetition is emphatic and designed to settle our faith in this great truth against all gainsayers.", "한국어번역":"이 반복은 강조적이며 모든 반대자에 맞서 이 위대한 진리에 우리의 믿음을 세우려는 의도이다.", "핵심통찰":"진리의 반복은 믿음의 기초를 세운다"},
        {"영어원문":"He was with God as the eternal Son with the eternal Father, in the bosom of the Father.", "한국어번역":"영원한 아들로서 영원한 아버지와 함께, 아버지의 품속에 계셨다.", "핵심통찰":"아버지와 아들의 영원한 친밀한 관계"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"영원 전부터 함께 계신 말씀 — 진리의 확인", "예화_적용":"중요한 진리는 반복하여 확인해야 한다"},
        {"대지":"서론", "내용":"2절은 1절의 반복처럼 보이지만 단순한 반복이 아니다. '이 말씀이' 곧 '이 분이' 태초에 이미 하나님과 함께 계셨다는 확인이다. 요한은 독자들이 이 진리를 놓치지 않도록 다시 한번 못을 박는다", "예화_적용":"계약서에 중요한 조항을 굵은 글씨로 표시하듯 성경도 핵심 진리를 반복한다"},
        {"대지":"1대지: 이 말씀이 (인격적 존재의 확인)", "내용":"'후토스'(이 분)는 앞서 말한 '로고스'가 추상적 원리가 아닌 구체적 인격임을 확인. 우리가 만날 수 있는 분", "예화_적용":"하나님은 철학적 개념이 아니라 만날 수 있는 인격이시다"},
        {"대지":"2대지: 태초에 (시간을 초월한 존재)", "내용":"'엔 아르케'의 반복은 그리스도의 존재가 시간 안에서 시작된 것이 아님을 재확인. 피조물과 근본적으로 다른 존재", "예화_적용":"시계를 만든 사람은 시계 안에 있지 않다. 시간을 만드신 분은 시간을 초월하신다"},
        {"대지":"3대지: 하나님과 함께 (관계 안의 존재)", "내용":"'프로스 톤 테온'의 반복은 삼위일체 안의 영원한 교제를 확증. 이 교제가 구원의 근거", "예화_적용":"아버지와 아들의 사랑의 교제가 우리를 향한 사랑의 근원이다"},
        {"대지":"결론", "내용":"요한은 1절의 진리를 2절에서 확인함으로써 우리의 신앙을 반석 위에 세운다. 그리스도의 영원한 선재와 신성은 기독교 신앙의 변할 수 없는 기초이다", "예화_적용":"기초가 흔들리면 건물 전체가 무너진다. 그리스도의 신성이라는 기초를 굳건히 세우라"}
    ],
