    표5_매튜헨리: [
        {"영어원문":"In him was life; the fountain of life was in him, both the life of nature and the life of grace.", "한국어번역":"그 안에 생명이 있었으니 생명의 샘이 그 안에 있어 자연의 생명과 은혜의 생명이 모두 그 안에 있다.", "핵심통찰":"모든 종류의 생명의 궁극적 근원은 그리스도"},
        {"영어원문":"The life was the light of men. The eternal Word is the great teacher and illuminator of mankind.", "한국어번역":"이 생명은 사람들의 빛이라. 영원한 말씀은 인류의 위대한 교사요 계몽자이시다.", "핵심통찰":"그리스도는 인류를 밝히시는 유일한 참빛"},
        {"영어원문":"That light which is the life of the soul shines from Christ and through him to us.", "한국어번역":"영혼의 생명인 그 빛은 그리스도에게서 나와 그를 통하여 우리에게 비춘다.", "핵심통찰":"영혼의 참된 생명은 그리스도의 빛에서만 온다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"생명과 빛의 근원이신 그리스도 — 어둠을 밝히는 생명", "예화_적용":"칠흑같은 어둠에 단 하나의 촛불이 비추면 어둠은 물러간다"},
        {"대지":"서론", "내용":"1-3절이 그리스도의 영원성과 창조를 선언했다면 4절은 그리스도와 인류의 관계를 밝힌다. 그 안에 생명이 있고 이 생명이 사람들의 빛이다. 창조자이신 그가 생명과 빛의 근원이시다", "예화_적용":"태양이 없으면 지구에 생명도 빛도 없듯이 그리스도가 없으면 영적 생명도 빛도 없다"},
        {"대지":"1대지: 그 안에 생명이 있었으니 (생명의 근원)", "내용":"'조에'는 단순한 생물학적 생명(비오스)이 아닌 영적·영원한 생명. 이 생명이 로고스 '안에' 본래부터 있었다. 빌려온 생명이 아닌 본래적 생명", "예화_적용":"샘물은 밖에서 물을 가져오지 않는다. 그 안에서 솟아난다. 그리스도가 바로 그 생명의 샘이시다"},
        {"대지":"2대지: 이 생명은 사람들의 빛이라 (진리의 조명)", "내용":"생명이 곧 빛이다. 그리스도의 생명은 어둠 속의 인류를 비추는 진리의 빛. 양심과 이성을 통해 모든 사람에게 비춤", "예화_적용":"한밤중에 길을 잃은 등산객에게 랜턴 하나가 전부이듯 그리스도의 빛이 인생의 유일한 길잡이"},
        {"대지":"3대지: 생명과 빛의 불가분 (참된 삶의 조건)", "내용":"생명 없이 빛이 없고 빛 없이 참된 생명이 없다. 그리스도를 떠난 생명은 어둠이요 그리스도를 떠난 빛은 생명이 없는 것", "예화_적용":"아무리 밝은 조명도 생명이 없으면 무의미하고 아무리 살아있어도 빛이 없으면 방향을 잃는다"},
        {"대지":"결론", "내용":"그리스도 안에 생명과 빛이 있다. 참된 삶을 원한다면 그리스도 안에 거하라. 진리를 알고 싶다면 그리스도에게 나아가라. 그가 생명이시요 빛이시다", "예화_적용":"예수님은 스스로 선언하셨다 — 나는 길이요 진리요 생명이니(요 14:6)"}
    ],
