        {"상황":"영적으로 메마르고 생기가 없는 분", "성경원리":"생명의 근원이신 그리스도 안에 거하면 생명이 흘러넘친다 (요 15:4-5)", "실제적용":"마른 땅에 물을 대듯 그리스도와의 교제 시간을 의도적으로 늘려라. 예배, 기도, 말씀이 생명의 통로"}
