        {"구분":"엘리야의 사명", "내용":"말 4:5 여호와의 크고 두려운 날이 이르기 전에 엘리야를 보내리니", "그리스도연결":"엘리야의 심령과 능력으로 온 세례 요한 (눅 1:17)"},
        {"구분":"모세의 보냄받음", "내용":"출 3:10-12 내가 너를 바로에게 보내어 백성을 인도하라", "그리스도연결":"하나님의 백성을 메시아에게 인도하기 위해 보내심 받은 요한"}
