        {"원어":"μονογενὴς θεός (모노게네스 테오스)", "의미_문법":"독생하신 하나님 - 형용사+명사. 유일하신 하나님", "설교포인트":"아들이 곧 하나님이심을 가장 강력하게 선언"},
        {"원어":"κόλπον (콜폰)", "의미_문법":"품속 - 명사 남성 단수 대격. 가슴/품", "설교포인트":"아버지와 아들의 가장 친밀한 관계"},
        {"원어":"ἐξηγήσατο (엑세게사토)", "의미_문법":"나타내셨다 - 동사 아오리스트. 설명하다/해석하다", "설교포인트":"'엑세게시스'(해석)의 어원 — 그리스도가 하나님을 해석해 주심"}
