    표5_매튜헨리: [
        {"영어원문":"Art thou Elias? He saith, I am not. He was not Elijah in person, though he came in the spirit and power of Elijah.", "한국어번역":"네가 엘리야냐? 나는 아니라 하니. 그는 인격적으로 엘리야가 아니었으나 엘리야의 심령과 능력으로 왔다.", "핵심통찰":"사명의 계승은 인물의 동일이 아닌 영적 능력의 이어짐"},
        {"영어원문":"Art thou that Prophet? No. His answers grow shorter and shorter, showing his desire to say nothing of himself.", "한국어번역":"네가 그 선지자냐? 아니라. 그의 대답이 점점 짧아지니 자기에 대해 아무것도 말하지 않으려는 의지를 보여준다.", "핵심통찰":"자기를 줄이는 것이 그리스도를 높이는 길"},
        {"영어원문":"John was more concerned to direct men to Christ than to claim any title for himself.", "한국어번역":"요한은 자기를 위해 어떤 칭호를 주장하는 것보다 사람들을 그리스도에게 인도하는 것에 더 관심이 있었다.", "핵심통찰":"칭호보다 사명이 중요하다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"세 번의 아니라 — 자기를 비우는 겸손의 힘", "예화_적용":"'아니오'라고 말할 줄 아는 사람이 '예'의 가치를 안다"},
        {"대지":"서론", "내용":"유대인들의 질문이 계속된다. 그리스도냐? 아니다. 엘리야냐? 아니다. 그 선지자냐? 아니다. 세 번의 부정 — 그리고 대답은 점점 짧아진다. 이 침묵이 23절의 외침보다 더 큰 설교가 된다", "예화_적용":"때로는 한마디의 '아니오'가 긴 설교보다 강력하다"},
        {"대지":"1대지: 네가 엘리야냐 — 아니라 (사명의 구별)", "내용":"요한은 엘리야의 심령과 능력으로 왔으나(눅 1:17) 문자적 엘리야는 아님. 사명의 계승과 인격의 동일은 다름", "예화_적용":"선생님의 정신을 이어받은 제자는 선생님의 가르침을 전하되 선생님 자체는 아니다"},
        {"대지":"2대지: 네가 그 선지자냐 — 아니라 (칭호의 거절)", "내용":"모세가 예언한 '그 선지자'(신 18:15)도 아님. 모든 위대한 칭호를 거절. 자기를 최소화하는 겸손의 극치", "예화_적용":"사람들이 주는 모든 칭호를 거절한 사람 — 이것이 진정한 위대함"},
        {"대지":"3대지: 점점 짧아지는 대답 (침묵의 설교)", "내용":"첫째 답변 8단어, 둘째 3단어, 셋째 1단어. 자기에 대한 말은 줄이고 그리스도에 대한 말은 늘리는 것이 참된 사역", "예화_적용":"자기 소개는 짧게, 그리스도 소개는 길게 — 이것이 사역자의 원칙"},
        {"대지":"결론", "내용":"요한의 세 번의 '아니라'가 우리에게 묻는다 — 당신은 자기가 아닌 것을 '아니라'고 말할 용기가 있는가? 자기를 비워야 그리스도가 채우신다", "예화_적용":"그릇이 비어야 물을 담을 수 있다. 자기를 비워야 그리스도가 채우신다"}
    ],
