        {"대지":"2대지: 그의 신들메 풀기도 (가장 낮은 섬김)", "내용":"신발 끈 풀기는 이방인 종에게나 시키는 가장 천한 일. 유대인 제자에게도 요구하지 않는 일. 요한은 이 자리도 감당 못한다", "예화_적용":"사장실 청소도 아닌 화장실 청소도 감당 못하겠다는 고백 — 이것이 위대함"},
        {"대지":"3대지: 감당치 못하겠노라 (자격 없음의 고백)", "내용":"'악시오스'는 합당함/자격. 요한은 자기에게 자격이 없다고 고백. 이 부자격 고백이 그리스도의 높으심을 가장 잘 드러냄", "예화_적용":"자기의 위대함을 주장하는 것보다 자기의 부족함을 고백하는 것이 더 큰 울림을 준다"},
        {"대지":"결론", "내용":"그리스도를 아는 것이 깊어질수록 겸손도 깊어진다. 이사야는 하나님을 보고 '화로다'(사 6:5)라 했고 베드로는 예수님을 보고 '나를 떠나소서'(눅 5:8)라 했다. 그리스도의 영광을 볼 때 참된 겸손이 시작된다", "예화_적용":"태양을 직접 보면 자기가 얼마나 작은지 알게 된다. 그리스도의 영광을 보면 참된 자기를 알게 된다"}
