        {"구절":"창 22:8", "연결점":"번제할 어린양은 하나님이 자기를 위하여 친히 준비하시리라", "구분":"구약"},
        {"구절":"시 40:6-8", "연결점":"제사와 예물을 기뻐하지 아니하시고 — 참된 제물의 예고", "구분":"구약"},
        {"구절":"요 1:29", "연결점":"보라 세상 죄를 지고 가는 하나님의 어린양이로다 — 첫 번째 선언", "구분":"신약"},
        {"구절":"고전 5:7", "연결점":"우리의 유월절 양 곧 그리스도께서 희생이 되셨느니라", "구분":"신약"},
        {"구절":"벧전 1:19-20", "연결점":"흠 없고 점 없는 어린양 같은 그리스도의 보배로운 피", "구분":"신약"},
        {"구절":"계 5:6", "연결점":"일찍 죽임을 당한 것 같은 어린양이 서 있는데", "구분":"신약"}
