        {"구절":"출 14:31", "연결점":"이스라엘이 하나님의 큰 능력을 보고 여호와를 경외하며 믿으니 — 표적을 보고 믿음", "구분":"구약"},
        {"구절":"출 33:18-22", "연결점":"나의 영광을 보여주소서 — 하나님 영광의 현현", "구분":"구약"},
        {"구절":"왕상 18:39", "연결점":"갈멜산에서 불이 내린 후 백성이 엎드려 말하되 여호와 그는 하나님이시로다 — 표적과 고백", "구분":"구약"},
        {"구절":"요 20:30-31", "연결점":"이것을 기록함은 너희로 믿게 하려 함이요 — 표적 기록의 목적", "구분":"신약"},
        {"구절":"요 1:14", "연결점":"말씀이 육신이 되어 우리 가운데 거하시매 우리가 그 영광을 보니 — 성육신의 영광", "구분":"신약"},
        {"구절":"요 20:29", "연결점":"보지 못하고 믿는 자들은 복되도다 — 보는 믿음에서 보지 않는 믿음으로", "구분":"신약"},
        {"구절":"고후 3:18", "연결점":"주의 영광을 보매 저와 같은 형상으로 변화하여 — 영광을 봄으로 변화됨", "구분":"신약"}
