        {"구분":"여러 날의 체류", "내용":"이스라엘이 광야의 각 지점에서 머물다 이동한 것처럼(민 33장), 예수님의 사역도 머묾과 이동의 리듬이 있었다", "그리스도연결":"때를 따라 일하시는 그리스도의 사역 방식 (요 7:6)"}
