        {"원어":"ἐγγὺς (엥귀스)", "의미_문법":"가까운 — 부사, 시간적 근접성, 절기가 임박했음을 나타냄", "설교포인트":"하나님의 때가 가까이 왔을 때 준비해야 한다"},
        {"원어":"ἀνέβη (아네베)", "의미_문법":"올라가다 — 동사, 아오리스트, 예루살렘은 해발 750m로 지리적으로 올라감, 또한 하나님의 성전으로 올라간다는 영적 의미", "설교포인트":"예배의 자리로 나아가는 것은 '올라감'이다"},
        {"원어":"Ἱεροσόλυμα (히에로솔뤼마)", "의미_문법":"예루살렘 — 고유명사, '평화의 기초'라는 뜻, 성전이 있는 거룩한 도시", "설교포인트":"예루살렘은 하나님의 임재의 중심이었으나, 이제 그리스도가 참 성전이시다"}
